//! The erased plumbing between the typed builder API and the engine.
//!
//! A transition's body is written with real types — `|p: Parcel, cfg: Config|`
//! — but the net stores one list of transitions whose bodies have nothing in
//! common. The typed body is therefore wrapped, once, at declaration time,
//! into a closure that speaks only in erased tokens: [`ErasedBody`]. The
//! wrapper is the only code that knows both sides, and it is generated by the
//! arity macro in [`crate::body`].
//!
//! Nothing here is nameable from outside the crate. The types are `pub` and
//! not `pub(crate)` only because they appear in the signatures of the sealed
//! traits' methods, which are reachable through the public traits; the module
//! is private, so the names never leave the crate.

use std::fmt;

use crate::place::ErasedToken;

/// One argument to a body, as the engine hands it over.
///
/// Which variant an input edge gets is fixed by its
/// [`EdgeKind`](crate::EdgeKind), so the extractors in [`crate::edge`] may
/// treat any other variant as a bug rather than a runtime error.
pub enum ErasedInput<'a> {
    /// One owned token: a [`TakeEdge`](crate::TakeEdge), or the clone a
    /// [`SnapshotEdge`](crate::SnapshotEdge) took of the front token.
    Token(ErasedToken),
    /// Every token of a place, oldest first: a
    /// [`TakeAllEdge`](crate::TakeAllEdge).
    Tokens(Vec<ErasedToken>),
    /// The front token of a place, borrowed where it lies: a
    /// [`MutateEdge`](crate::MutateEdge). The borrow is why a transition
    /// with such an edge runs inline instead of being handed to a worker.
    Borrowed(&'a mut ErasedToken),
    /// What an extractor leaves behind when it has moved the value out. An
    /// input is extracted exactly once, so this is never seen by a body.
    Taken,
}

impl fmt::Debug for ErasedInput<'_> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ErasedInput::Token(_) => f.write_str("Token(..)"),
            ErasedInput::Tokens(tokens) => write!(f, "Tokens(x{})", tokens.len()),
            ErasedInput::Borrowed(_) => f.write_str("Borrowed(..)"),
            ErasedInput::Taken => f.write_str("Taken"),
        }
    }
}

/// One argument per input edge, in declaration order.
#[derive(Debug)]
pub struct ErasedInputs<'a>(Vec<ErasedInput<'a>>);

impl<'a> ErasedInputs<'a> {
    /// Collects the arguments for one firing. The engine builds this in
    /// declaration order; the generated wrapper consumes it in the same
    /// order.
    #[cfg_attr(
        not(test),
        expect(
            dead_code,
            reason = "the firing stages that build the arguments arrive in a later slice; \
                      the crate's own tests already call bodies with them"
        )
    )]
    pub(crate) fn new(inputs: Vec<ErasedInput<'a>>) -> Self {
        ErasedInputs(inputs)
    }

    /// Hands out each argument once, in order, so that the wrapper can pass
    /// several `&mut` arguments at once: the items of an
    /// [`IterMut`](std::slice::IterMut) borrow the slice, not the iterator,
    /// so they may all be alive together.
    pub(crate) fn iter_mut(&mut self) -> std::slice::IterMut<'_, ErasedInput<'a>> {
        self.0.iter_mut()
    }
}

/// What a body produced: tokens for its output places, or a failure.
///
/// The `Ok` form is one list of `(output index, token)` pairs rather than a
/// list per place, because that single shape carries every output form:
/// positional (slot *i* to output *i*), routed (index resolved from the
/// payload type at build time) and `Distribution` (index looked up from the
/// place the author named).
pub enum ErasedOutcome {
    /// Tokens to distribute, each tagged with the index of the output place
    /// it belongs to. Order is the order they will be pushed.
    Ok(Vec<(usize, ErasedToken)>),
    /// The body returned `Err`, or panicked (from a later slice on). The net
    /// is not written to; failure handling decides what happens to the
    /// consumed tokens.
    Err(Box<dyn std::error::Error + Send + Sync>),
}

impl fmt::Debug for ErasedOutcome {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ErasedOutcome::Ok(tokens) => write!(f, "Ok(x{})", tokens.len()),
            ErasedOutcome::Err(error) => write!(f, "Err({error})"),
        }
    }
}

/// A transition body with its types erased, as the net stores it.
///
/// `FnMut`, so a body may keep private state between firings; `Send + Sync`,
/// so it may run on another thread and so the net stays `Send + Sync`;
/// `for<'a>`, so one body can be called with borrows of whatever tokens this
/// firing found in the places.
pub(crate) type ErasedBody =
    Box<dyn for<'a> FnMut(ErasedInputs<'a>) -> ErasedOutcome + Send + Sync>;
